//! The obligation calendar — what is due, on what day, between now and the horizon.
//!
//! A monthly total is the wrong shape for the question people actually have. Rent on the 1st, a card
//! minimum on the 3rd and an insurance renewal on the 5th is a very different week from the same
//! money spread across thirty days, and a month-level figure cannot see the difference. The failure
//! this prevents is arriving at a heavy week with a balance that was, on a monthly view, fine.
//!
//! # Stepping is the whole problem, and it is not obvious
//!
//! A monthly charge is NOT every 30 days. Step a 15 January bill by 30 days twelve times and it lands
//! on 11 December — five days and, at the boundaries, a whole month wrong. Billing anniversaries are
//! CALENDAR facts, so monthly, quarterly and annual step by calendar months and keep their day, while
//! weekly and biweekly step by days because that is what they actually are.
//!
//! And **the anchor never moves**. A bill on the 31st stepped into February CLAMPS to the 28th for
//! that month, then returns to the 31st in March — it does not walk backwards a few days a year, and
//! it certainly does not roll over into the following month, which is what naive date arithmetic
//! does.
use crate::money::{sum, Currency, Money};
use crate::position::Position;
use crate::recurring::{Cadence, Recurring};

pub use days_in_month::days_in_month;
pub use add_days::add_days;
pub use add_calendar_months::add_calendar_months;
pub(crate) use step::step;
pub(crate) use occurrences::occurrences;
pub use months_between::months_between;
pub use due_between::due_between;
pub use month_total::month_total;
pub use heaviest_window::heaviest_window;
pub use minimums_on::minimums_on;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ObligationKind {
    Recurring,
    Minimum,
}

impl ObligationKind {
    pub fn label(self) -> &'static str {
        match self {
            ObligationKind::Recurring => "recurring",
            ObligationKind::Minimum => "minimum",
        }
    }
}

/// How much the DATE is to be trusted. The amount is a separate question.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Confidence {
    Observed,
    Assumed,
}

impl Confidence {
    pub fn label(self) -> &'static str {
        match self {
            Confidence::Observed => "observed",
            Confidence::Assumed => "assumed",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Obligation {
    /// `YYYY-MM-DD` it is expected to hit.
    pub date: String,
    pub label: String,
    pub account: String,
    /// POSITIVE amount due — a calendar of outgoings does not need signs to say which way they go.
    pub amount: Money,
    pub kind: ObligationKind,
    pub confidence: Confidence,
    /// For a recurring charge, how metronomic the observed occurrences were.
    pub regularity: Option<f64>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct MonthTotal {
    pub month: String,
    pub total: Money,
    pub count: usize,
}

#[derive(Debug, Clone, PartialEq)]
pub struct ObligationCalendar {
    pub from: String,
    pub to: String,
    pub obligations: Vec<Obligation>,
    pub by_month: Vec<MonthTotal>,
    /// The month that costs the most. The one to have money in place for.
    pub heaviest: Option<MonthTotal>,
    /// Everything the calendar DECIDED rather than observed.
    pub notes: Vec<String>,
}

pub struct CalendarOptions<'a> {
    pub from: &'a str,
    pub to: &'a str,
    /// Day of the month a debt's minimum is actually due, where it is known.
    pub minimum_due_day: &'a [(String, u32)],
    /// Include charges that look cancelled. Off by default; they are reported as a note either way.
    pub include_lapsed: bool,
}

impl<'a> CalendarOptions<'a> {
    pub fn new(from: &'a str, to: &'a str) -> Self {
        CalendarOptions { from, to, minimum_due_day: &[], include_lapsed: false }
    }
}

pub fn build_calendar(recurring: &[Recurring], position: Option<&Position>, opts: &CalendarOptions) -> ObligationCalendar {
    let mut notes: Vec<String> = Vec::new();
    let mut obligations: Vec<Obligation> = Vec::new();

    let lapsed: Vec<&Recurring> = recurring.iter().filter(|r| r.lapsed).collect();
    if !lapsed.is_empty() && !opts.include_lapsed {
        let names: Vec<&str> = lapsed.iter().map(|r| r.label.as_str()).collect();
        notes.push(format!(
            "{} charge(s) look cancelled and are NOT on the calendar — {}. If one of them renews, the months below are light by that much.",
            lapsed.len(),
            names.join(", ")
        ));
    }
    let irregular = recurring.iter().filter(|r| r.cadence == Cadence::Irregular).count();
    if irregular > 0 {
        notes.push(format!("{irregular} charge(s) recur on no predictable schedule and have no date here — they will still cost money."));
    }

    for r in recurring {
        if r.lapsed && !opts.include_lapsed {
            continue;
        }
        for date in occurrences(r, opts.from, opts.to) {
            obligations.push(Obligation {
                date,
                label: r.label.clone(),
                account: r.account.clone(),
                amount: r.typical,
                kind: ObligationKind::Recurring,
                // The DATE is observed — it came from a real rhythm. Whether the AMOUNT repeats is
                // what `regularity` and the charge's own amount stability are for.
                confidence: if r.regularity >= 0.8 { Confidence::Observed } else { Confidence::Assumed },
                regularity: Some(r.regularity),
            });
        }
    }

    for a in position.map(|p| p.accounts.as_slice()).unwrap_or(&[]) {
        let (Some(minimum), Some(_owed)) = (a.minimum_payment, a.owed) else { continue };
        if minimum.minor == 0 {
            continue;
        }
        let day = opts.minimum_due_day.iter().find(|(id, _)| *id == a.account).map(|(_, d)| *d as i64);
        if day.is_none() {
            notes.push(format!(
                "the due day for {}'s minimum is unknown — it is placed on the 1st, the earliest it could plausibly fall, so this calendar cannot be optimistic about it",
                a.institution
            ));
        }
        for month in months_between(opts.from, opts.to) {
            let (Some(y), Some(m)) = (month.get(0..4).and_then(|s| s.parse::<i64>().ok()), month.get(5..7).and_then(|s| s.parse::<i64>().ok())) else { continue };
            let at = format!("{month}-{:02}", day.unwrap_or(1).min(days_in_month(y, m)));
            if at.as_str() < opts.from || at.as_str() > opts.to {
                continue;
            }
            obligations.push(Obligation {
                date: at,
                label: format!("{} minimum", a.institution),
                account: a.account.clone(),
                amount: minimum,
                kind: ObligationKind::Minimum,
                confidence: if day.is_none() { Confidence::Assumed } else { Confidence::Observed },
                regularity: None,
            });
        }
    }

    obligations.sort_by(|x, y| x.date.cmp(&y.date).then(x.label.cmp(&y.label)));

    let currency = obligations.first().map(|o| o.amount.currency).or_else(|| position.map(|p| p.currency)).unwrap_or(Currency::USD);
    let mut buckets: Vec<(String, Vec<&Obligation>)> = Vec::new();
    for o in &obligations {
        let key = o.date[..7.min(o.date.len())].to_string();
        match buckets.iter_mut().find(|(k, _)| *k == key) {
            Some((_, b)) => b.push(o),
            None => buckets.push((key, vec![o])),
        }
    }
    buckets.sort_by(|a, b| a.0.cmp(&b.0));
    let by_month: Vec<MonthTotal> = buckets
        .iter()
        .filter_map(|(month, os)| {
            let amounts: Vec<Money> = os.iter().map(|o| o.amount).collect();
            sum(&amounts, currency).ok().map(|total| MonthTotal { month: month.clone(), total, count: os.len() })
        })
        .collect();

    // The FIRST heaviest month on a tie, because the calendar reads forward and the earlier one is
    // the one arriving first — `max_by_key` would hand back the last.
    let heaviest = by_month.iter().fold(None::<&MonthTotal>, |best, m| match best {
        Some(b) if b.total.minor >= m.total.minor => Some(b),
        _ => Some(m),
    });

    ObligationCalendar {
        from: opts.from.to_string(),
        to: opts.to.to_string(),
        heaviest: heaviest.cloned(),
        by_month,
        obligations,
        notes,
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct Window {
    pub from: String,
    pub to: String,
    pub total: Money,
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::account::Kind;
    use crate::money::usd;
    use crate::position::{AccountPosition, Position};

    // SYNTHETIC FIXTURES ONLY.
    fn rec(label: &str, cadence: Cadence, minor: i64, last_seen: &str, regularity: f64, lapsed: bool) -> Recurring {
        Recurring {
            key: label.to_lowercase(),
            label: label.to_string(),
            account: "chk".to_string(),
            cadence,
            typical: usd(minor),
            annualised: usd(0),
            occurrences: 3,
            first_seen: "2026-01-01".to_string(),
            last_seen: last_seen.to_string(),
            regularity,
            amount_stability: 1.0,
            lapsed,
        }
    }

    fn card_position() -> Position {
        Position {
            as_of: "2026-06-30".to_string(),
            currency: Currency::USD,
            accounts: vec![AccountPosition {
                account: "visa".to_string(),
                institution: "chase".to_string(),
                kind: Kind::Credit,
                balance: usd(-200_000),
                as_of: "2026-06-30".to_string(),
                rolled_forward: 0,
                is_debt: true,
                owed: Some(usd(200_000)),
                credit_limit: None,
                available: None,
                utilisation: None,
                apr: None,
                daily_interest: None,
                minimum_payment: Some(usd(5_000)),
            }],
            net_worth: usd(0),
            liquid: usd(0),
            total_debt: usd(200_000),
            daily_interest: usd(0),
            minimums_due: usd(5_000),
            weighted_apr: None,
            complete: true,
            provenance: String::new(),
            problems: Vec::new(),
        }
    }

    #[test]
    fn a_bill_on_the_thirty_first_clamps_into_february_and_then_comes_back() {
        // THE ANCHOR NEVER MOVES. Measured against the TypeScript, a full year from 2026-01-31.
        let walk: Vec<String> = (0..13).map(|i| add_calendar_months("2026-01-31", i)).collect();
        assert_eq!(
            walk,
            vec![
                "2026-01-31", "2026-02-28", "2026-03-31", "2026-04-30", "2026-05-31", "2026-06-30",
                "2026-07-31", "2026-08-31", "2026-09-30", "2026-10-31", "2026-11-30", "2026-12-31", "2027-01-31"
            ]
        );
        // The failure this prevents: stepping the CLAMPED date would give 2026-03-28, and the bill
        // would walk backwards three days a year. Repeatedly re-anchoring is the whole design.
        assert_eq!(add_calendar_months("2026-01-31", 2), "2026-03-31");
        assert_ne!(add_calendar_months("2026-01-31", 2), "2026-03-28");
    }

    #[test]
    fn february_is_correct_in_a_leap_year_and_the_century_rule_holds() {
        assert_eq!(add_calendar_months("2024-01-31", 1), "2024-02-29");
        assert_eq!(add_calendar_months("2023-01-31", 1), "2023-02-28");
        assert_eq!(add_calendar_months("2026-01-29", 1), "2026-02-28");
        // 2100 is divisible by 4 and is NOT a leap year. The every-four-years approximation would
        // put a bill on 29 February 2100.
        assert_eq!(days_in_month(2100, 2), 28);
        assert_eq!(days_in_month(2000, 2), 29);
        assert_eq!(days_in_month(2024, 2), 29);
    }

    #[test]
    fn stepping_backwards_crosses_the_year_boundary() {
        assert_eq!(add_calendar_months("2026-03-31", -1), "2026-02-28");
        assert_eq!(add_calendar_months("2026-01-15", -1), "2025-12-15");
        assert_eq!(add_calendar_months("2026-01-31", -13), "2024-12-31");
    }

    #[test]
    fn day_arithmetic_crosses_months_and_years() {
        assert_eq!(add_days("2026-02-27", 2), "2026-03-01");
        assert_eq!(add_days("2026-12-31", 1), "2027-01-01");
        assert_eq!(add_days("2026-03-01", -1), "2026-02-28");
        // An unparseable date comes back untouched. Returning the epoch would sort it to the front
        // of every calendar as a phantom obligation in 1970.
        assert_eq!(add_days("not-a-date", 5), "not-a-date");
    }

    #[test]
    fn months_between_is_inclusive_at_both_ends() {
        assert_eq!(months_between("2026-01-15", "2026-04-02"), vec!["2026-01", "2026-02", "2026-03", "2026-04"]);
        assert_eq!(months_between("2026-01-15", "2026-01-20"), vec!["2026-01"]);
    }

    #[test]
    fn the_calendar_places_every_charge_on_its_own_day() {
        let c = build_calendar(
            &[rec("RENT", Cadence::Monthly, 120_000, "2026-06-05", 1.0, false), rec("NETFLIX", Cadence::Monthly, 1_599, "2026-06-12", 0.7, false), rec("BUS", Cadence::Weekly, 250, "2026-06-25", 1.0, false)],
            Some(&card_position()),
            &CalendarOptions::new("2026-07-01", "2026-08-31"),
        );
        let got: Vec<(&str, &str, i64, &str)> = c.obligations.iter().map(|o| (o.date.as_str(), o.label.as_str(), o.amount.minor, o.confidence.label())).collect();
        assert_eq!(
            got,
            vec![
                ("2026-07-01", "chase minimum", 5_000, "assumed"),
                ("2026-07-02", "BUS", 250, "observed"),
                ("2026-07-05", "RENT", 120_000, "observed"),
                ("2026-07-09", "BUS", 250, "observed"),
                // Regularity 0.7 is below the 0.8 bar, so the DATE is assumed rather than observed.
                ("2026-07-12", "NETFLIX", 1_599, "assumed"),
                ("2026-07-16", "BUS", 250, "observed"),
                ("2026-07-23", "BUS", 250, "observed"),
                ("2026-07-30", "BUS", 250, "observed"),
                ("2026-08-01", "chase minimum", 5_000, "assumed"),
                ("2026-08-05", "RENT", 120_000, "observed"),
                ("2026-08-06", "BUS", 250, "observed"),
                ("2026-08-12", "NETFLIX", 1_599, "assumed"),
                ("2026-08-13", "BUS", 250, "observed"),
                ("2026-08-20", "BUS", 250, "observed"),
                ("2026-08-27", "BUS", 250, "observed"),
            ]
        );
        let months: Vec<(&str, i64, usize)> = c.by_month.iter().map(|m| (m.month.as_str(), m.total.minor, m.count)).collect();
        assert_eq!(months, vec![("2026-07", 127_849, 8), ("2026-08", 127_599, 7)]);
        assert_eq!(c.heaviest.as_ref().unwrap().month, "2026-07");
        assert_eq!(minimums_on(&c).len(), 2);
        assert_eq!(due_between(&c, "2026-07-01", "2026-07-06").len(), 3);
        // A month with nothing due is ZERO, which is a real answer — unlike a projection's absent
        // total, which means the projection does not know.
        assert_eq!(month_total(&c, "2026-09", Currency::USD).minor, 0);
    }

    #[test]
    fn the_heaviest_seven_days_is_what_a_monthly_view_cannot_see() {
        let c = build_calendar(
            &[rec("RENT", Cadence::Monthly, 120_000, "2026-06-05", 1.0, false), rec("NETFLIX", Cadence::Monthly, 1_599, "2026-06-12", 0.7, false), rec("BUS", Cadence::Weekly, 250, "2026-06-25", 1.0, false)],
            Some(&card_position()),
            &CalendarOptions::new("2026-07-01", "2026-08-31"),
        );
        let w = heaviest_window(&c, 7).expect("there are obligations");
        assert_eq!((w.from.as_str(), w.to.as_str(), w.total.minor), ("2026-07-01", "2026-07-07", 125_250));
        // July totals 127849 across the month, and all but 2599 of it lands in ONE WEEK. A
        // month-level view sees an affordable month; this sees the week that breaks it.
        assert_eq!(month_total(&c, "2026-07", Currency::USD).minor - w.total.minor, 2_599);
    }

    #[test]
    fn a_cancelled_charge_is_off_the_calendar_and_the_omission_is_stated() {
        let c = build_calendar(
            &[rec("OLDGYM", Cadence::Monthly, 5_000, "2026-03-01", 1.0, true), rec("ODD", Cadence::Irregular, 900, "2026-06-01", 1.0, false)],
            None,
            &CalendarOptions::new("2026-07-01", "2026-07-31"),
        );
        assert!(c.obligations.is_empty());
        assert!(c.heaviest.is_none(), "no obligations is ABSENT, not a zero month");
        assert_eq!(c.notes.len(), 2);
        assert!(c.notes[0].contains("look cancelled") && c.notes[0].contains("OLDGYM"));
        // The irregular one has no date, and the note says it will still cost money — silence would
        // read as "nothing else is coming".
        assert!(c.notes[1].contains("no predictable schedule"));
    }

    #[test]
    fn including_the_lapsed_ones_puts_them_back_and_drops_the_note() {
        let opts = CalendarOptions { include_lapsed: true, ..CalendarOptions::new("2026-07-01", "2026-07-31") };
        let c = build_calendar(&[rec("OLDGYM", Cadence::Monthly, 5_000, "2026-03-01", 1.0, true)], None, &opts);
        assert_eq!(c.obligations.len(), 1);
        assert_eq!(c.obligations[0].date, "2026-07-01");
        assert!(c.notes.is_empty(), "nothing was omitted, so there is nothing to warn about");
    }

    #[test]
    fn an_unknown_due_day_goes_on_the_first_because_a_calendar_must_not_be_optimistic() {
        let c = build_calendar(&[], Some(&card_position()), &CalendarOptions::new("2026-07-01", "2026-07-31"));
        assert_eq!(c.obligations.len(), 1);
        assert_eq!(c.obligations[0].date, "2026-07-01");
        assert_eq!(c.obligations[0].confidence, Confidence::Assumed);
        assert!(c.notes[0].contains("earliest it could plausibly fall"));

        // Told the real day, it is placed there and the guess disappears.
        let known = [("visa".to_string(), 17u32)];
        let c2 = build_calendar(&[], Some(&card_position()), &CalendarOptions { minimum_due_day: &known, ..CalendarOptions::new("2026-07-01", "2026-07-31") });
        assert_eq!(c2.obligations[0].date, "2026-07-17");
        assert_eq!(c2.obligations[0].confidence, Confidence::Observed);
        assert!(c2.notes.is_empty());
    }

    #[test]
    fn a_due_day_past_the_end_of_a_short_month_clamps_rather_than_spilling_over() {
        let known = [("visa".to_string(), 31u32)];
        let c = build_calendar(&[], Some(&card_position()), &CalendarOptions { minimum_due_day: &known, ..CalendarOptions::new("2026-02-01", "2026-02-28") });
        assert_eq!(c.obligations[0].date, "2026-02-28", "the 31st of February is the 28th, not 3 March");
    }
}
